<?php $rows=[]; foreach($offers as $o){ $actions='<div class="action-row"><a class="btn btn-secondary" href="'.site_url('bloc2/offers/'.$o['id']).'">Consulter</a>'; if($o['statut']==='BROUILLON'){$actions.='<form method="post" action="'.site_url('bloc2/offers/'.$o['id'].'/publish').'">'.csrf_field().'<button class="btn btn-primary">Publier</button></form>';} if($o['statut']==='PUBLIEE'){$actions.='<form method="post" action="'.site_url('bloc2/offers/'.$o['id'].'/close').'">'.csrf_field().'<button class="btn btn-danger">Clôturer</button></form>';} $actions.='<a class="btn btn-white" href="'.site_url('bloc2/applications?offre_emploi_id='.$o['id']).'">Candidatures</a></div>'; $rows[]=[esc($o['titre']),esc($o['demande_intitule']??('Demande #'.$o['demande_recrutement_id'])),ui_date($o['date_publication']),ui_date($o['date_cloture']),ui_raw(ui_badge($o['statut'])),(string)$o['candidature_count'],ui_raw($actions)]; } ?>
<?= ui_panel('Liste des offres', ui_table(['Titre','Demande','Publication','Clôture','Statut','Candidatures','Actions'],$rows,'Aucune offre.')) ?>
